query:
-- Enable Oracle VM sync on the existing row (id=1), or insert a new row with it enabled
INSERT INTO admin_config (id, oracleSyncEnabled) VALUES (1, 1)
ON DUPLICATE KEY UPDATE oracleSyncEnabled = 1;

-- Verify
SELECT id, oracleSyncEnabled, lastOracleSyncAt, lastSyncInserted FROM admin_config LIMIT 1;

